import java.nio.file.Path;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a new {@link File} inside {@code dir} with a unique name derived from {@code name}.
     * The method validates that the resulting file path stays within {@code dir} to prevent
     * directory‑traversal attacks. It also normalizes the path and rejects invalid or
     * empty inputs.
     *
     * @param dir  the base directory where the file should be created; must not be {@code null}
     * @param name the desired file name; may contain a query string which will be stripped
     * @return a {@link File} instance that does not yet exist on disk
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null},
     *                                  empty, or if the resolved path would escape {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Directory cannot be null");
        }
        if (name == null || name.isEmpty()) {
            throw new IllegalArgumentException("Name cannot be null or empty");
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve and normalize the target path
        Path dirPath = dir.toPath().toAbsolutePath().normalize();
        Path targetPath;
        try {
            targetPath = dirPath.resolve(name).normalize();
        } catch (InvalidPathException e) {
            throw new IllegalArgumentException("Invalid file name: " + name, e);
        }

        // Ensure the target path is still inside the base directory
        if (!targetPath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                    "File path escapes the target directory: " + targetPath);
        }

        File file = targetPath.toFile();

        // Split name into prefix and suffix for uniqueness handling
        int dot = name.lastIndexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);

        int index = 2;
        while (file.exists()) {
            String newName = prefix + "-" + index++ + suffix;
            targetPath = dirPath.resolve(newName).normalize();
            file = targetPath.toFile();
        }

        // Create parent directories if necessary
        File parent = file.getParentFile();
        if (parent != null && !parent.exists() && !parent.mkdirs()) {
            throw new RuntimeException("Failed to create directories: " + parent);
        }

        return file;
    }

    // other methods
}
