import java.util.Calendar;
import static java.util.Calendar.*;

/**
 * Sets the specified calendar field to a value derived from {@code i} and the
 * configured {@code offset}.  The method performs strict validation to
 * prevent illegal values that could cause the caller to enter an infinite
 * loop or corrupt the calendar state.
 *
 * @param c the calendar instance to modify
 * @param i the raw value supplied by the caller
 * @throws IllegalArgumentException if the resulting value is outside the
 *         valid range for the calendar field or if {@code field} is null
 */
void setTo(Calendar c, int i) {
    // Defensive null check – a null field would otherwise cause a NPE
    if (field == null) {
        throw new IllegalArgumentException("CalendarField 'field' must not be null");
    }

    // Compute the intended value after applying the offset
    int value = i - offset;

    // Validate that the value lies within the calendar's legal bounds
    int min = c.getActualMinimum(field);
    int max = c.getActualMaximum(field);
    if (value < min || value > max) {
        throw new IllegalArgumentException(
                String.format("Attempted to set %s to %d, which is outside the valid range [%d,%d]",
                              CalendarField.name(field), value, min, max));
    }

    // Finally set the field – this will never trigger an infinite loop
