     */
    private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
        // Canonical path of the extraction root – used for containment checks
        final String targetDirCanonical = targetDirectory.getCanonicalPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            final String entryName = nextEntry.getName();

            /* ------------------------------------------------------------------ *
             * 1️⃣  Basic entry‑name validation                                      *
             * ------------------------------------------------------------------ */
