            // After normalisation the path must still be relative
            if (normalizedEntryPath.isAbsolute()) {
                throw new IOException("Absolute entry path not allowed: " + entryName);
            }

            /* ------------------------------------------------------------------ *
             * 2️⃣  Resolve the full target file path                               *
             * ------------------------------------------------------------------ */
            final File targetFile = new File(targetDirectory, normalizedEntryPath.toString());
            final String targetFileCanonical = targetFile.getCanonicalPath();

            // Ensure the canonical path stays within the extraction root
            if (!targetFileCanonical.startsWith(targetDirCanonical)) {
                throw new IOException("Expanding " + entryName + " would create file outside of "
                        + targetDirectory);
            }

            /* ------------------------------------------------------------------ *
             * 3️⃣  Handle directories and files                                   *
             * ------------------------------------------------------------------ */
            if (nextEntry.isDirectory()) {
                if (!targetFile.isDirectory() && !targetFile.mkdirs()) {
                    throw new IOException("Failed to create directory " + targetFile);
                }
            } else {
                // Ensure parent directories exist
                final File parentDir = targetFile.getParentFile();
                if (!parentDir.isDirectory() && !parentDir.mkdirs()) {
                    throw new IOException("Failed to create directory " + parentDir);
                }

                // Write the entry data using NIO with explicit options
                try (OutputStream out = Files.newOutputStream(
                        targetFile.toPath(),
                        StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING,
                        StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

