    /**
     * Securely parses XML from a {@link InputSource} using a {@link DocumentBuilderFactory}
     * that has all external entity resolution disabled. This protects against XXE attacks.
     */
    private Document parseSecure(InputSource source) throws Exception {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        // Enable secure processing
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        // Disallow DOCTYPE declarations
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        // Disable external entities
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        dbf.setXIncludeAware(false);
        dbf.setExpandEntityReferences(false);
        // Explicitly deny access to external DTDs and schemas
        dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
        dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

        DocumentBuilder db = dbf.newDocumentBuilder();
        Document doc = db.parse(source);

        // Close the underlying stream if present to avoid resource leaks
        if (source.getByteStream() != null) {
            try {
                source.getByteStream().close();
            } catch (IOException e) {
                // Log and ignore – the document has already been parsed
            }
        }
        return doc;
    }

    @Override
    protected Object doGetDocument(Exchange exchange, Object body) throws Exception {
        if (body == null) {
